unsafe fn aptx_prediction_filtering(
    mut prediction: *mut aptx_prediction,
    mut reconstructed_difference: int32_t,
    mut order: c_int,
) {
    let pred = prediction;
    let pred_ref = unsafe { &mut *pred }; // SAFETY: caller guarantees `prediction` is a valid, unique pointer for mutation during this function.

    let reconstructed_sample = clip_intp2(
        reconstructed_difference + pred_ref.predicted_sample,
        23 as c_uint,
    );

    let predictor = clip_intp2(
        ((pred_ref.s_weight[0] as int64_t * pred_ref.previous_reconstructed_sample as int64_t
            + pred_ref.s_weight[1] as int64_t * reconstructed_sample as int64_t)
            >> 22) as int32_t,
        23 as c_uint,
    );

    pred_ref.previous_reconstructed_sample = reconstructed_sample;

    let reconstructed_differences =
        aptx_reconstructed_differences_update(pred, reconstructed_difference, order);

    let srd0 = ((reconstructed_difference > 0) as c_int - (reconstructed_difference < 0) as c_int)
        as int32_t
        * ((1 as int32_t) << 23);

    let mut predicted_difference: int64_t = 0;
    let mut i: c_int = 0;

    while i < order {
        let idx = i as usize;
        let rd_prev = unsafe { *reconstructed_differences.offset((-i - 1) as isize) }; // SAFETY: `aptx_reconstructed_differences_update` returns a pointer into a buffer with at least `order + 1` accessible prior elements, matching the original code's indexing.
        let srd = (rd_prev >> 31) | 1;
        let dw = pred_ref.d_weight[idx];
        let new_dw = dw - rshift32(dw - srd * srd0, 8 as c_uint);
        pred_ref.d_weight[idx] = new_dw;

        let rd_cur = unsafe { *reconstructed_differences.offset(-(i as isize)) }; // SAFETY: same bounds reasoning as above; the original code accesses element `-i` for all `i < order`.
        predicted_difference += rd_cur as int64_t * new_dw as int64_t;

        i += 1;
    }

    pred_ref.predicted_difference = clip_intp2((predicted_difference >> 22) as int32_t, 23 as c_uint);
    pred_ref.predicted_sample =
        clip_intp2(predictor + pred_ref.predicted_difference, 23 as c_uint);
}

